def get_la_question(id):
    if Question.query.get(id) is None:
        abort(404)
    if Question.query.get(id).questionType == "simple":
        return Simple_Question.query.get(id).to_json()
    elif Question.query.get(id).questionType == "multiple":
        return Multiple_Question.query.get(id).to_json()

def add_la_question(json):
    q = Question(json['title'], json['questionType'], json['questionnaire_id'])
    db.session.add(q)
    if json['questionType'] == "simple":
        q = Simple_Question(json['title'], json['questionnaire_id'], json['reponse'])
        if not isinstance(json['reponse'], str):
            abort(400)
    elif json['questionType'] == "multiple":
        q = Multiple_Question(json['title'], json['questionnaire_id'], json['proposition1'], json['proposition2'], json['reponse'])
        if not isinstance(json['reponse'], int):
            abort(400)
        if not isinstance(json['proposition1'], str):
            abort(400)
        if not isinstance(json['proposition2'], str):
            abort(400)
    db.session.add(q)
    db.session.commit()
    return q.to_json()

def update_la_question(id):
    question = Question.query.get(id)
    question.title = request.json['title']
    question.questionType = request.json['questionType']
    question.questionnaire_id = request.json['questionnaire_id']
    if question.questionType == "simple":
        question = Simple_Question.query.get(id)
        question.reponse = request.json['reponse']
        if not isinstance(request.json['reponse'], str):
            abort(400)
        db.session.commit()
        return question.to_json()
    elif question.questionType == "multiple":
        question = Multiple_Question.query.get(id)
        question.reponse = int(request.json['reponse'])
        question.proposition1 = request.json['proposition1']
        question.proposition2 = request.json['proposition2']
        if not isinstance(request.json['reponse'], int):
            abort(400)
        if not isinstance(request.json['proposition1'], str):
            abort(400)
        if not isinstance(request.json['proposition2'], str):
            abort(400)
        db.session.commit()
        return question.to_json()
    db.session.commit()
    return question.to_json()

def delete_la_question(id):
    question = Question.query.get(id)
    if question.questionType == "simple":
        question_simple = Simple_Question.query.get(id)
        db.session.delete(question_simple)
        db.session.commit()
    elif question.questionType == "multiple":
        question_multiple = Multiple_Question.query.get(id)
        db.session.delete(question_multiple)
        db.session.commit()
    db.session.delete(question)
    db.session.commit()
    return question.to_json()

